create extension if not exists "pgcrypto";
create table if not exists profiles(id uuid primary key default gen_random_uuid(),auth_user_id uuid unique,role text not null check(role in ('teacher','center','super_admin','manager','supervisor')),full_name text not null,email text,phone text,status text not null default 'pending',created_at timestamptz default now());
create table if not exists subjects(id bigserial primary key,name_ar text not null,name_en text not null,sort_order int default 0);
create table if not exists teachers(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id) on delete cascade,age int,gender text,years_experience int default 0,workplace text,bio_ar text,bio_en text,whatsapp text,photo_url text,online boolean default true,in_person boolean default true,individual boolean default true,group_lesson boolean default false,individual_price numeric(10,2),group_price numeric(10,2),rating numeric(3,2) default 0,is_featured boolean default false,featured_subject_id bigint references subjects(id),approved boolean default false,active boolean default true);
create table if not exists teacher_subjects(teacher_id uuid references teachers(id) on delete cascade,subject_id bigint references subjects(id) on delete cascade,primary key(teacher_id,subject_id));
create table if not exists centers(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles(id) on delete cascade,name_ar text not null,name_en text,location text,google_maps_url text,whatsapp text,phone text,logo_url text,gallery jsonb default '[]'::jsonb,individual_price numeric(10,2),group_price numeric(10,2),is_featured boolean default false,approved boolean default false,active boolean default true);
create table if not exists bookings(id uuid primary key default gen_random_uuid(),teacher_id uuid references teachers(id),parent_name text not null,phone text not null,email text,lesson_type text,delivery_type text,booking_date date,booking_time time,notes text,status text default 'pending',created_at timestamptz default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(),teacher_id uuid references teachers(id) on delete cascade,reviewer_name text,rating int check(rating between 1 and 5),comment text,approved boolean default false,created_at timestamptz default now());
